async function rebuildSignalStudioLighting(
  userId: string,
  showId: string,
  options: {
    preferredProvider?: ImageProviderName;
    signal?: AbortSignal;
    keywords?: readonly string[];
  } = {},
): Promise<ReturnType<typeof getBotcastShow>> {
  const show = getBotcastShow(db, userId, showId);
  if (!show.dayAtmosphere.imageId || !show.nightAtmosphere.imageId) {
    throw new HttpError(
      409,
      "Install both the Light and Dark studios before refreshing Studio lighting.",
    );
  }

  type StudioSourceRow = {
    id: string;
    bot_id: string | null;
    origin: string | null;
    local_rel_path: string | null;
  };
  const loadSource = (imageId: string, label: string): Buffer => {
    const source = db
      .prepare(
        `SELECT id, bot_id, origin, local_rel_path
           FROM images
          WHERE id = ? AND user_id = ?`,
      )
      .get(imageId, userId) as StudioSourceRow | undefined;
    if (
      !source ||
      source.origin !== "botcast" ||
      !source.local_rel_path?.trim()
    ) {
      throw new HttpError(
        404,
        `${label} studio source is not available locally.`,
      );
    }
    try {
      return readGeneratedImageBytes(source.local_rel_path);
    } catch {
      throw new HttpError(404, `${label} studio source file was not found.`);
    }
  };

  const signal = options.signal ?? new AbortController().signal;
  if (signal.aborted) throw new DOMException("cancelled", "AbortError");
  const dayBytes = loadSource(show.dayAtmosphere.imageId, "Light");
  const nightBytes = loadSource(show.nightAtmosphere.imageId, "Dark");
  let generated = await generateSignalStudioLightingMap(dayBytes, nightBytes);
  let prompt = `Derived Studio lighting receiver map for ${show.name}`;
  let revisedPrompt = prompt;
  let quality = "derived";
  let provider: "local" | "openai" = "local";
  let model = "prism-studio-lighting-v1";

  const user = getUserRow(userId);
  const effectiveProvider = resolveImageProviderName({
    savedProvider: user.preferred_image_provider,
    requestedProvider:
      options.preferredProvider ?? user.preferred_image_provider,
    offlineOnly: imageContextIncludesOfflineOnlyBot(db, userId, [
      show.hostBotId,
    ]),
  });
  const preferredOpenAiImageModel =
    user.preferred_openai_image_model?.trim() ?? "";
  if (
    effectiveProvider === "openai" &&
    !isDisabledModelChoice(preferredOpenAiImageModel)
  ) {
    const userKey = decryptUserKey(userId);
    const apiKey =
      getOpenAiApiKeyForUser(userId, userKey) ?? config.openAiApiKey;
    const imageModel = DEFAULT_OPENAI_IMAGE_MODEL_ID;
    const imageQuality = "high";
    enterUsageSession({
      db,
      userId,
      privacyScope: "normal",
      mode: "sandbox",
      surface: "images",
      conversationId: null,
      botId: show.hostBotId,
    });
    try {
      const receiverPrompt = withSignalGenerationKeywords(
        SIGNAL_STUDIO_LIGHTING_RECEIVER_EDIT_PROMPT,
        options.keywords,
      );
      const result = await editImage(receiverPrompt, dayBytes, apiKey, {
        model: imageModel,
        size: "1536x1024",
        quality: imageQuality,
        signal,
      });
      const receiverBytes = await readOpenAiGeneratedImageBytes(result, signal);
      recordImageUsage({
        provider: "openai",
        model: result.model,
        purpose: "image_generation",
        imageCount: 1,
        imageSize: "1536x1024",
        imageQuality,
        createdAt: new Date().toISOString(),
      });
      generated = await generateSignalStudioLightingMap(
        dayBytes,
        nightBytes,
        receiverBytes,
      );
      prompt = receiverPrompt;
      revisedPrompt = result.revisedPrompt;
      quality = imageQuality;
      provider = "openai";
      model = result.model;
    } catch (error) {
      if (signal.aborted) throw error;
      console.warn(
        "[signal-artwork] generated Studio receiver matte unavailable; using deterministic default",
        error instanceof Error ? error.message : error,
      );
    }
  }
  if (signal.aborted) throw new DOMException("cancelled", "AbortError");

  const imageId = randomId(12);
  const localRelPath = buildGeneratedImageRelativePath(userId, imageId);
  const displayUrl = `/api/images/${encodeURIComponent(imageId)}/file`;
  const createdAt = new Date().toISOString();
  const relatedBotIds = serializeImageRelatedBotIds(
    [show.hostBotId],
    show.hostBotId,
  );
  let savedShow = show;
  try {
    writeGeneratedImageBytes(localRelPath, generated.pngBytes);
    db.prepare(
      `INSERT INTO images
         (id, user_id, conversation_id, bot_id, related_bot_ids, origin,
          prompt, revised_prompt, url, size, quality, provider, model,
          local_rel_path, purpose, created_at)
       VALUES (?, ?, NULL, ?, ?, 'botcast', ?, ?, ?, ?, ?,
               ?, ?, ?, 'signal_studio_lighting', ?)`,
    ).run(
      imageId,
      userId,
      show.hostBotId,
      relatedBotIds,
      prompt,
      revisedPrompt,
      displayUrl,
      `${generated.width}x${generated.height}`,
      quality,
      provider,
      model,
      localRelPath,
      createdAt,
    );
    try {
      savedShow = updateBotcastShow(db, userId, show.id, {
        studioLighting: {
          imageUrl: displayUrl,
          imageId,
          sourceDayImageId: show.dayAtmosphere.imageId,
          sourceNightImageId: show.nightAtmosphere.imageId,
          revision: show.studioLighting.revision + 1,
          status: "ready",
        },
      });
    } catch (error) {
      db.prepare("DELETE FROM images WHERE id = ? AND user_id = ?").run(
        imageId,
        userId,
      );
      throw error;
    }
  } catch (error) {
    tryUnlinkGeneratedImageFile(localRelPath);
    throw error;
  }

  const previousImageId = show.studioLighting.imageId;
  if (previousImageId && previousImageId !== imageId) {
    const previous = db
      .prepare(
        `SELECT local_rel_path
           FROM images
          WHERE id = ? AND user_id = ? AND bot_id = ?
            AND origin = 'botcast' AND purpose = 'signal_studio_lighting'`,
      )
      .get(previousImageId, userId, show.hostBotId) as
      { local_rel_path: string | null } | undefined;
    if (previous) {
      db.prepare("DELETE FROM images WHERE id = ? AND user_id = ?").run(
        previousImageId,
        userId,
      );
      if (previous.local_rel_path?.trim()) {
        tryUnlinkGeneratedImageFile(previous.local_rel_path);
      }
    }
  }
  return savedShow;
}

