async function startPrismStorySession(
  context: PrismCapabilityContext,
  input: PrismJsonObject,
) {
  const powerTheme = readResolvedPowerTheme(input.theme);
  const botIds = normalizeStoryCreateBotIds(input.botIds);
  const storyBots = loadStoryBotProfiles(db, context.userId, botIds);
  const user = getUserRow(context.userId);
  const requestedProvider = readProvider(input.preferredProvider);
  const anyOfflineProtected = storyBots.some((bot) => !bot.onlineEnabled);
  let effectiveProvider: ProviderName =
    context.hardLocal || anyOfflineProtected
      ? "local"
      : (requestedProvider ?? user.preferred_provider);
  const explicitModelOverride =
    context.hardLocal || anyOfflineProtected
      ? null
      : readModelOverride(input.modelOverride);
  const storyModelOverride = explicitModelOverride;
  const premise = readOptionalString(input.premise);
  const responseLane = effectiveProvider === "local" ? "local" : "online";
  const openAiApiKey =
    responseLane === "online"
      ? (getOpenAiApiKeyForUser(context.userId, context.userKey) ??
        config.openAiApiKey)
      : undefined;
  const anthropicApiKey =
    responseLane === "online"
      ? (getAnthropicApiKeyForUser(context.userId, context.userKey) ??
        config.anthropicApiKey)
      : undefined;
  const catalog = await buildModelCatalog(
    responseLane === "online" ? openAiApiKey : undefined,
    user.secondary_ollama_host,
    responseLane === "online" ? anthropicApiKey : undefined,
  );
  const hiddenModelIds = parseHiddenBotModelIds(user.hidden_bot_model_ids);
  const resolvedAuto = resolveAutoModel({
    provider: effectiveProvider,
    lane: responseLane,
    explicitModelOverride: storyModelOverride,
    hiddenModelIds,
    catalog,
    onlineAutoProviderBias: clampOnlineAutoProviderBias(
      user.online_auto_provider_bias,
    ),
    routingContext: {
      surface: "story",
      inputText: premise ?? "",
      outputTokens: 2_048,
      simulatedEffortEnabled: true,
    },
  });
  effectiveProvider = resolvedAuto.provider;
  const storedReasoningEffort = resolveUserModelReasoningEffort(db, {
    userId: context.userId,
    provider: resolvedAuto.provider,
    modelId: resolvedAuto.model,
  });
  const hiddenModels = new Set(hiddenModelIds);
  const candidateAllowlist = (
    responseLane === "local" ? catalog.local : catalog.online
  )
    .filter((entry) => !hiddenModels.has(entry.id))
    .map((entry): AutoFallbackModelRef => ({
      provider:
        entry.provider === "anthropic"
          ? "anthropic"
          : entry.provider === "local"
            ? "local"
            : "openai",
      model: entry.id,
    }));
  const primaryRef: AutoFallbackModelRef = {
    provider: resolvedAuto.provider,
    model: resolvedAuto.model,
  };
  const configuredFallbacks = parseStoredAutoFallbackChain(
    user.auto_fallback_chain,
  );
  const generationChain =
    autoFallbackResolvedChain(primaryRef, configuredFallbacks) ?? [primaryRef];
  const session = createStorySession(db, context.userId, {
    botIds,
    premise,
    provider: effectiveProvider,
    model: resolvedAuto.model,
    routing: {
      v: 1,
      lane: responseLane,
      modelSelectionKind: resolvedAuto.autoRoute ? "auto" : "fixed",
      candidateAllowlist,
      fallbackChain: generationChain.slice(1),
      policyVersion: resolvedAuto.autoRoute?.v ?? 1,
      ...(resolvedAuto.autoRoute ? { autoRoute: resolvedAuto.autoRoute } : {}),
    },
  });
  void Promise.resolve(
    runWithUsageSession(
      {
        db,
        userId: context.userId,
        privacyScope: "normal",
        mode: "story",
        surface: "story",
      },
      async () => {
        let generated = session;
        for (const [index, attempt] of generationChain.entries()) {
          generated = await generateStorySessionEpisode(
            db,
            context.userId,
            session.id,
            {
              provider: providerFactoryOverride(
                attempt.provider,
                attempt.provider === "openai" ? openAiApiKey : undefined,
                user.secondary_ollama_host,
                attempt.provider === "anthropic"
                  ? anthropicApiKey
                  : undefined,
              ),
              providerName: attempt.provider,
              model: attempt.model,
              turbo: resolveUserModelTurboMode(db, {
                userId: context.userId,
                provider: attempt.provider,
                modelId: attempt.model,
              }),
              bots: storyBots,
              premise,
              ...(powerTheme ? { theme: powerTheme } : {}),
              ...(index === 0
                ? resolvedAuto.autoRoute?.reasoningEffort ??
                  storedReasoningEffort
                  ? {
                      reasoningEffort:
                        resolvedAuto.autoRoute?.reasoningEffort ??
                        storedReasoningEffort,
                    }
                  : {}
                : { reasoningEffort: "none" }),
            },
          );
          if (generated.status !== "failed") return generated;
        }
        return generated;
      },
    ),
  ).catch((error) => {
    console.warn("[story] generation job failed", error);
  });
  return session;
}

const prismCapabilityRegistry = createPrismDomainCapabilityRegistry({
  primaryOllamaHost: config.ollamaHost,
  startStorySession: startPrismStorySession,
  onBotProfileChanged: (context, botId) => {
    const user = getUserRow(context.userId);
    queueBotSemanticFacetsRefresh({
      db,
      userId: context.userId,
      botId,
      prismDefaultLlmModel: user.prism_default_llm_model,
      provider: auxiliaryProviderFactoryOverride(
        user.prism_default_llm_model ?? undefined,
        dualOllamaWorkloadOptions(user),
      ),
    });
  },
  readElevenLabsBalance: async (context) => {
    const apiKey = getElevenLabsApiKeyForUser(context.userId, context.userKey);
    if (!apiKey) {
      throw new HttpError(
        409,
        "Save an ElevenLabs API key to this account before checking credits.",
      );
    }
    return getElevenLabsCreditBalance(apiKey);
  },
  generateBotDraft: async (context, brief) => {
    const user = getUserRow(context.userId);
    const model = resolveAuxiliaryOllamaModel(user.prism_default_llm_model);
    const generated = await runWithUsageSession(
      {
        db,
        userId: context.userId,
        privacyScope: "normal",
        mode: "system",
        surface: "bots",
      },
      () =>
        generateBotDraft({
          prompt: brief,
          provider: auxiliaryProviderFactoryOverride(
            user.prism_default_llm_model ?? undefined,
            dualOllamaWorkloadOptions(user),
          ),
          providerName: "local",
          model,
          responseMode: "local",
        }),
    );
    if (generated.draft.powers.length === 0) return generated.draft;
    const compiled = await runWithUsageSession(
      {
        db,
        userId: context.userId,
        privacyScope: "normal",
        mode: "system",
        surface: "bots",
      },
      () =>
        compileBotPowers({
          provider: auxiliaryProviderFactoryOverride(
            user.prism_default_llm_model ?? undefined,
            dualOllamaWorkloadOptions(user),
          ),
          botName: generated.draft.name,
          systemPrompt: JSON.stringify(generated.draft.profile),
          powers: generated.draft.powers,
          targetBots: db
            .prepare(
              "SELECT id, name FROM bots WHERE user_id = ? ORDER BY name, id",
            )
            .all(context.userId) as Array<{ id: string; name: string }>,
        }),
    );
    return {
      ...generated.draft,
      powers: compiled.powers,
    };
  },
  generateBotContextualField: async (
    context,
    { botName, currentValue, direction, profile },
  ) => {
    const user = getUserRow(context.userId);
    const model = resolveAuxiliaryOllamaModel(user.prism_default_llm_model);
    const generated = await runWithUsageSession(
      {
        db,
        userId: context.userId,
        privacyScope: "normal",
        mode: "system",
        surface: "bots",
      },
      () =>
        generateBotField({
          fieldKey: "profile.advancedPrompt",
          currentValue,
          context: {
            botName,
            profile,
            playerDirection: direction,
            instruction:
              "Rewrite the advanced prompt so this bot uniquely satisfies the player direction while preserving its established identity.",
          },
          provider: auxiliaryProviderFactoryOverride(
            user.prism_default_llm_model ?? undefined,
            dualOllamaWorkloadOptions(user),
          ),
          providerName: "local",
          model,
          responseMode: "local",
        }),
    );
    if (typeof generated.value !== "string" || !generated.value.trim()) {
      throw new Error("The auxiliary model returned an invalid bot update.");
    }
    return {
      value: generated.value,
      provider: generated.providerNameUsed,
      model: generated.modelUsed,
    };
  },
  generateCoffeeGroupIdentity: async (context, { brief, bots }) => {
    const user = getUserRow(context.userId);
    const model = resolveAuxiliaryOllamaModel(user.prism_default_llm_model);
    const raw = await runWithUsageSession(
      {
        db,
        userId: context.userId,
        privacyScope: "normal",
        mode: "system",
        surface: "coffee",
      },
      () =>
        auxiliaryProviderFactoryOverride(
          user.prism_default_llm_model ?? undefined,
          dualOllamaWorkloadOptions(user),
        ).generateResponse(
          [
            {
              role: "system",
              content: [
                "Create one distinctive Coffee group identity for the supplied PRISM characters.",
                "The contrast should be funny because of who these specific characters are, not because of generic randomness.",
                "Write a short evocative group name and one playable premise that gives everyone a reason to talk.",
                "Return one shared group, never a separate entry for each character.",
                "Do not mention prompts, bots, AI, character sheets, or internal product mechanics.",
                'Return only JSON: {"name":"2-5 words","premise":"1-2 sentences"}',
              ].join("\n"),
            },
            {
              role: "user",
              content: [
                `Player direction: ${brief.slice(0, 2_000)}`,
                "Characters:",
                ...bots.map(
                  (bot) =>
                    `- ${bot.name}: ${bot.profileSummary.replace(/\s+/gu, " ").slice(0, 1_200)}`,
                ),
              ].join("\n"),
            },
          ],
          {
            model,
            temperature: 0.8,
            maxTokens: 320,
            jsonMode: true,
            usagePurpose: "chat_reply",
          },
        ),
    );
    const start = raw.indexOf("{");
    const end = raw.lastIndexOf("}");
    if (start < 0 || end <= start) {
      throw new Error(
        "The auxiliary model returned an invalid Coffee identity.",
      );
    }
    let parsed: unknown;
    try {
      parsed = JSON.parse(raw.slice(start, end + 1));
    } catch {
      throw new Error(
        "The auxiliary model returned an invalid Coffee identity.",
      );
    }
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      throw new Error(
        "The auxiliary model returned an invalid Coffee identity.",
      );
    }
    const record = parsed as Record<string, unknown>;
    const name =
      typeof record.name === "string"
        ? record.name.trim().replace(/\s+/gu, " ").slice(0, 120)
        : "";
    const premise =
      typeof record.premise === "string"
        ? record.premise.trim().replace(/\s+/gu, " ").slice(0, 1_000)
        : "";
    if (!name || !premise) {
      throw new Error(
        "The auxiliary model returned an incomplete Coffee identity.",
      );
    }
    return {
      name,
      premise,
      provider: "local",
      model,
    };
  },
  generateSignalBooking: async (context, { showId, guestBotId, direction }) => {
    const user = getUserRow(context.userId);
    const model = resolveAuxiliaryOllamaModel(user.prism_default_llm_model);
    let resolvedProvider = "local";
    let resolvedModel: string | null = model;
    const generated = await runWithUsageSession(
      {
        db,
        userId: context.userId,
        privacyScope: "normal",
        mode: "system",
        surface: "signal",
      },
      () =>
        generateBotcastBookingSuggestion(
          db,
          context.userId,
          showId,
          {
            guestBotId,
            field: "booking",
            modelOverride: model,
          },
          {
            preferredProvider: "local",
            responseMode: "local",
            preferredLocalModel: model,
            secondaryOllamaHost: user.secondary_ollama_host,
            providerFactory: providerFactoryOverride,
            direction,
            onGenerationResolved: (provider, selectedModel) => {
              resolvedProvider = provider;
              resolvedModel = selectedModel;
            },
          },
        ),
    );
    if (
      !("topic" in generated) ||
      !generated.generated ||
      !generated.topic.trim() ||
      !generated.producerBrief.trim()
    ) {
      throw new HttpError(
        503,
        generated.failureReason === "provider_request_failed"
          ? "Signal could not reach the auxiliary model."
          : "Signal could not synthesize a valid booking.",
      );
    }
    return {
      topic: generated.topic,
      producerBrief: generated.producerBrief,
      provider: resolvedProvider,
      model: resolvedModel,
    };
  },
});

function slateRecoveryRootDirectory(): string {
  const configured = process.env.SLATE_RECOVERY_DIR?.trim();
  return configured || join(dirname(resolveDbPath()), "slate-recovery");
}

function slateRecoveryMirrorDirectory(): string | null {
  return process.env.SLATE_RECOVERY_MIRROR_DIR?.trim() || null;
}

function protectSlateMutation<T>(
  value: T,
  userId: string,
  projectId: string,
  reason: string,
  milestone = false,
): T {
  if (!slateRecoveryCoordinator) return value;
  const input = { userId, projectId, reason };
  if (milestone) slateRecoveryCoordinator.scheduleMilestone(input);
  else slateRecoveryCoordinator.schedulePostMutation(input);
  return value;
}

function protectSlateBeforeRisk(userId: string, projectId: string): void {
  if (!slateRecoveryCoordinator) return;
  writeSlateRecoveryGeneration(
    db,
    userId,
    projectId,
    slateRecoveryRootDirectory(),
    { mirrorDirectory: slateRecoveryMirrorDirectory() },
  );
}

function slateRecoveryStatus(
  userId: string,
  projectId: string,
): SlateRecoveryCoordinatorStatus | null {
  return slateRecoveryCoordinator?.status({ userId, projectId }) ?? null;
}

function slateProjectIdsForUser(userId: string): string[] {
  return (
    db
      .prepare("SELECT id FROM slate_projects WHERE user_id = ? ORDER BY id")
      .all(userId) as Array<{ id: string }>
  ).map((row) => row.id);
}

/**
 * Quiesces recovery writers before removing their local and mirror copies.
 * The returned callback is used only when the following SQLite deletion/reset
 * fails and the still-existing projects need protection enabled again.
 */
async function retireAndPurgeSlateRecoveryProjects(
  userId: string,
  projectIds: readonly string[],
): Promise<() => void> {
  const coordinator = slateRecoveryCoordinator;
  const references = projectIds.map((projectId) => ({ userId, projectId }));
  if (coordinator) {
    await Promise.all(
      references.map((reference) => coordinator.retireProject(reference)),
    );
  }
  const resume = () => {
    if (!coordinator) return;
    for (const reference of references) coordinator.resumeProject(reference);
  };

  try {
    const roots = new Set<string>([slateRecoveryRootDirectory()]);
    const mirror = slateRecoveryMirrorDirectory();
    if (mirror) roots.add(mirror);
    for (const root of roots) {
      for (const projectId of projectIds) {
        purgeSlateRecoveryProjectGenerations(root, projectId);
      }
    }
  } catch (error) {
    resume();
    throw error;
  }
  return resume;
}

function slateArchivePayload(body: unknown): Uint8Array {
  if (!(body instanceof Uint8Array)) {
    throw new HttpError(400, "A .slate archive file is required.");
  }
  return body;
}

function rethrowSlateArchiveError(error: unknown): never {
  if (
    error instanceof SlateArchiveImportError ||
    error instanceof SlateArchiveZipError
  ) {
    throw new HttpError(400, error.message);
  }
  if (
    error instanceof Error &&
    /(?:project|series) not found/i.test(error.message)
  ) {
    throw new HttpError(404, error.message);
  }
  throw error;
}

function normalizeBotAudioVoiceProfilesForResponse<
  T extends Record<string, unknown>,
>(
  bot: T,
): T & {
  authored_audio_voice_profile: BotAudioVoiceProfileV1;
  audio_voice_profile_override: BotAudioVoiceProfileV1 | null;
} {
  return {
    ...bot,
    authored_audio_voice_profile:
      parseStoredBotAudioVoiceProfileV1(bot.authored_audio_voice_profile) ??
      normalizeBotAudioVoiceProfileV1(undefined),
    audio_voice_profile_override: parseStoredBotAudioVoiceProfileV1(
      bot.audio_voice_profile_override,
    ),
  };
}

function persistPremiumVoiceDefaults(
  userId: string,
  voices: ReadonlyArray<{ voiceId: string }>,
): { assignedBotIds: string[]; assignedDefaultPrism: boolean } {
  const user = getUserRow(userId);
  const bots = db
    .prepare(
      `SELECT id, authored_audio_voice_profile, audio_voice_profile_override
         FROM bots
        WHERE user_id = ?`,
    )
    .all(userId) as Array<{
    id: string;
    authored_audio_voice_profile: string | null;
    audio_voice_profile_override: string | null;
  }>;
  // #region agent log
  fetch("http://127.0.0.1:7914/ingest/796e4cfe-51fc-4e0c-8265-ef32bc063af2", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "X-Debug-Session-Id": "2836be",
    },
    body: JSON.stringify({
      sessionId: "2836be",
      hypothesisId: "A,C,E",
      location: "server.ts:persistPremiumVoiceDefaults:entry",
      message: "Persisting premium voice defaults",
      data: {
        userId,
        voiceCount: voices.length,
        rawPrismProfileLength:
          typeof user.prism_default_bot_audio_voice_profile === "string"
            ? user.prism_default_bot_audio_voice_profile.length
            : 0,
        rawPrismProfilePreview:
          typeof user.prism_default_bot_audio_voice_profile === "string"
            ? user.prism_default_bot_audio_voice_profile.slice(0, 220)
            : null,
        botCount: bots.length,
      },
      timestamp: Date.now(),
    }),
  }).catch(() => {});
  // #endregion
  const initialization = initializePremiumVoiceDefaults({
    userId,
    voices,
    bots: bots.map((bot) => ({
      id: bot.id,
      authoredAudioVoiceProfile: bot.authored_audio_voice_profile,
      audioVoiceProfileOverride: bot.audio_voice_profile_override,
    })),
    prismDefaultBotAudioVoiceProfile:
      user.prism_default_bot_audio_voice_profile,
  });
  if (
    initialization.botUpdates.length === 0 &&
    !initialization.prismDefaultBotAudioVoiceProfile
  ) {
    // #region agent log
    fetch("http://127.0.0.1:7914/ingest/796e4cfe-51fc-4e0c-8265-ef32bc063af2", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Debug-Session-Id": "2836be",
      },
      body: JSON.stringify({
        sessionId: "2836be",
        hypothesisId: "A",
        location: "server.ts:persistPremiumVoiceDefaults:noop",
        message: "No premium voice writes needed",
        data: { userId },
        timestamp: Date.now(),
      }),
    }).catch(() => {});
    // #endregion
    return { assignedBotIds: [], assignedDefaultPrism: false };
  }

  db.exec("BEGIN IMMEDIATE TRANSACTION");
  try {
    const updateBot = db.prepare(
      `UPDATE bots
          SET audio_voice_profile_override = ?
        WHERE id = ? AND user_id = ?`,
    );
    for (const update of initialization.botUpdates) {
      updateBot.run(
        serializeBotAudioVoiceProfileV1(update.audioVoiceProfileOverride),
        update.id,
        userId,
      );
    }
    if (initialization.prismDefaultBotAudioVoiceProfile) {
      const serialized = serializeBotAudioVoiceProfileV1(
        initialization.prismDefaultBotAudioVoiceProfile,
      );
      // #region agent log
      fetch("http://127.0.0.1:7914/ingest/796e4cfe-51fc-4e0c-8265-ef32bc063af2", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-Debug-Session-Id": "2836be",
        },
        body: JSON.stringify({
          sessionId: "2836be",
          hypothesisId: "A,D",
          location: "server.ts:persistPremiumVoiceDefaults:writePrism",
          message: "Overwriting Default Prism voice profile",
          data: {
            userId,
            writtenPreview: serialized.slice(0, 280),
            assignedVoiceId:
              initialization.prismDefaultBotAudioVoiceProfile.elevenLabsVoiceId ??
              null,
          },
          timestamp: Date.now(),
        }),
      }).catch(() => {});
      // #endregion
      db.prepare(
        `UPDATE users
            SET prism_default_bot_audio_voice_profile = ?
          WHERE id = ?`,
      ).run(serialized, userId);
    }
    db.exec("COMMIT");
  } catch (error) {
    db.exec("ROLLBACK");
    throw error;
  }
  return {
    assignedBotIds: initialization.botUpdates.map((update) => update.id),
    assignedDefaultPrism: Boolean(
      initialization.prismDefaultBotAudioVoiceProfile,
    ),
  };
}

function resolveLocalVoiceDelivery(
  profileValue: BotAudioVoiceProfileV1,
  allowOperatingSystemVoices: boolean,
): {
  localEngine: ReturnType<typeof resolveLocalVoiceEngine>;
  pronunciation: ResolvedLocalVoicePronunciationV1;
  speechprint: ResolvedLocalVoiceSpeechprintV1;
  usingSystemVoice: boolean;
} {
  const profile = normalizeBotAudioVoiceProfileV1(profileValue);
  const localAccent = resolveLocalAccentFallback({
    accentDefinitionId: profile.accentDefinitionId,
    pronunciationBase: profile.pronunciationBase,
    speechprintInfluence: profile.speechprintInfluence,
  });
  const localProfile = {
    ...profile,
    pronunciationBase: localAccent.pronunciationBase,
    speechprintInfluence: localAccent.speechprintInfluence,
  };
  const speechprintProfile = normalizeLocalVoiceSpeechprintV1({
    influence: localProfile.speechprintInfluence,
    strength: localProfile.speechprintStrength,
    variationSeed: localProfile.speechprintVariationSeed,
  });
  const localEngine = resolveLocalVoiceEngine({
    preference: localProfile.localEnginePreference,
    speechprintActive: localVoiceSpeechprintIsActive(speechprintProfile),
    pronunciationOverrideActive: localVoicePronunciationOverrideIsActive(
      localProfile.pronunciationBase,
      localProfile.accentLocale,
    ),
  });
  const usingSystemVoice =
    allowOperatingSystemVoices && Boolean(localProfile.systemVoiceName);
  const pronunciation = resolveLocalVoicePronunciation({
    profile: localProfile,
    localEngine,
    usingSystemVoice,
  });
  return {
    localEngine,
    pronunciation,
    usingSystemVoice,
    speechprint: resolveLocalVoiceSpeechprint({
      profile: localProfile,
      localEngine,
      usingSystemVoice,
      pronunciation,
    }),
  };
}

function setVoicePronunciationHeaders(
  response: ServerResponse,
  pronunciation: ResolvedLocalVoicePronunciationV1 | undefined,
): void {
  if (!pronunciation) return;
  response.setHeader("x-prism-pronunciation-status", pronunciation.status);
  response.setHeader(
    "x-prism-pronunciation-requested",
    pronunciation.requestedBase,
  );
  response.setHeader(
    "x-prism-pronunciation-source-locale",
    pronunciation.sourceLocale,
  );
  response.setHeader(
    "x-prism-pronunciation-base-locale",
    pronunciation.resolvedBaseLocale,
  );
  if (pronunciation.reason) {
    response.setHeader(
      "x-prism-pronunciation-reason",
      pronunciation.reason,
    );
  }
}

function setVoiceSpeechprintHeaders(
  response: ServerResponse,
  speechprint: ResolvedLocalVoiceSpeechprintV1 | undefined,
): void {
  if (!speechprint) return;
  response.setHeader("x-prism-speechprint-status", speechprint.status);
  response.setHeader(
    "x-prism-speechprint-id",
    speechprint.requestedInfluence,
  );
  response.setHeader("x-prism-speechprint-strength", speechprint.strength);
  response.setHeader("x-prism-speechprint-base-locale", speechprint.baseLocale);
  if (speechprint.reason) {
    response.setHeader("x-prism-speechprint-reason", speechprint.reason);
  }
  if (speechprint.rulesetVersion) {
    response.setHeader(
      "x-prism-speechprint-ruleset",
      speechprint.rulesetVersion,
    );
  }
  if (speechprint.rulesetSha256) {
    response.setHeader(
      "x-prism-speechprint-sha256",
      speechprint.rulesetSha256,
    );
  }
}

function sendVoiceWave(
  response: ServerResponse,
  wave: Buffer,
  engineUsed:
    | "builtin"
    | "builtin-babble"
    | "builtin-local-fallback"
    | "builtin-provider-fallback",
  characterCount: number,
  includeAlignment = false,
  localEngine?: ReturnType<typeof resolveLocalVoiceEngine>,
  pronunciation?: ResolvedLocalVoicePronunciationV1,
  speechprint?: ResolvedLocalVoiceSpeechprintV1,
): void {
  response.setHeader("cache-control", "no-store");
  response.setHeader("x-prism-voice-engine", engineUsed);
  response.setHeader("x-prism-voice-characters", String(characterCount));
  setVoicePronunciationHeaders(response, pronunciation);
  setVoiceSpeechprintHeaders(response, speechprint);
  if (localEngine) {
    response.setHeader("x-prism-local-voice-engine", localEngine.resolved);
    response.setHeader("x-prism-voice-model", PRISM_INSTANT_VOICE_MODEL_ID);
    response.setHeader(
      "x-prism-voice-model-sha256",
      PRISM_INSTANT_VOICE_MODEL_SHA256,
    );
    if (localEngine.notice) {
      response.setHeader(
        "x-prism-voice-notice",
        encodeURIComponent(localEngine.notice),
      );
    }
  }
  if (includeAlignment) {
    response.setHeader("x-prism-audio-content-type", "audio/wav");
    response.setHeader("x-prism-voice-alignment", "none");
    json(response, 200, {
      ok: true,
      audioBase64: wave.toString("base64"),
      audioContentType: "audio/wav",
      alignment: null,
      normalizedAlignment: null,
    });
    return;
  }
  response.statusCode = 200;
  response.setHeader("content-type", "audio/wav");
  response.setHeader("content-length", String(wave.byteLength));
  response.end(wave);
}

async function sendLocalVoiceWaveStream(args: {
  response: ServerResponse;
  text: string;
  profile: BotAudioVoiceProfileV1;
  engineUsed:
    | "builtin"
    | "builtin-babble"
    | "builtin-local-fallback"
    | "builtin-provider-fallback";
  allowOperatingSystemVoices: boolean;
  signal: AbortSignal;
  localEngine?: ReturnType<typeof resolveLocalVoiceEngine>;
  pronunciation?: ResolvedLocalVoicePronunciationV1;
  speechprint?: ResolvedLocalVoiceSpeechprintV1;
  protectedPhrases?: readonly string[];
  performancePlan?: VoicePerformancePlanV1 | null;
  /** Enables restrained punctuation orchestration for Kokoro, never system TTS. */
  punctuationPacing?: boolean;
}): Promise<void> {
  type LocalVoiceStreamItem =
    | {
        kind: "speech";
        text: string;
        sourceStart: number;
        sourceEnd: number;
      }
    | VoicePerformanceVocalActionSegmentV1;
  const hasVocalActions =
    args.performancePlan?.segments.some(
      (segment) => segment.kind === "vocal-action",
    ) === true;
  const streamItems: LocalVoiceStreamItem[] = [];
  if (hasVocalActions) {
    for (const segment of args.performancePlan!.segments) {
      if (segment.kind === "vocal-action") {
        streamItems.push(segment);
        continue;
      }
      streamItems.push(
        ...splitLocalVoiceStreamSegments(
          segment.text,
          segment.sourceStart,
          { punctuationPacing: args.punctuationPacing === true },
        ).map((chunk) => ({
          kind: "speech" as const,
          ...chunk,
        })),
      );
    }
  } else {
    streamItems.push(
      ...splitLocalVoiceStreamSegments(args.text, 0, {
        punctuationPacing: args.punctuationPacing === true,
      }).map((chunk) => ({
        kind: "speech" as const,
        ...chunk,
      })),
    );
  }
  if (streamItems.length === 0)
    throw new Error("Speakable assistant text is required.");
  const speechItemIndexes = streamItems.flatMap((item, index) =>
    item.kind === "speech" ? [index] : [],
  );
  const firstSpeechItemIndex = speechItemIndexes[0] ?? -1;
  const lastSpeechItemIndex = speechItemIndexes.at(-1) ?? -1;
  const generate = (text: string) =>
    builtinVoiceWaveGeneratorOverride({
      text,
      profile: args.profile,
      allowOperatingSystemVoices: args.allowOperatingSystemVoices,
      signal: args.signal,
      protectedPhrases: args.protectedPhrases,
    });
  // Prepare the first phrase before committing a 200 response so startup
  // failures still retain the route's normal actionable 503 behavior.
  const firstItem = streamItems[0]!;
  const firstWave = firstItem.kind === "speech"
    ? await generate(firstItem.text)
    : null;
  if (args.signal.aborted) throw new DOMException("Aborted", "AbortError");

  args.response.statusCode = 200;
  args.response.setHeader("cache-control", "no-store");
  args.response.setHeader(
    "content-type",
    "application/x-ndjson; charset=utf-8",
  );
  args.response.setHeader(
    "x-prism-voice-stream",
    hasVocalActions ? "wav-chunks-v2" : "wav-chunks-v1",
  );
  args.response.setHeader("x-prism-voice-engine", args.engineUsed);
  args.response.setHeader("x-prism-voice-characters", String(args.text.length));
  if (args.punctuationPacing === true) {
    args.response.setHeader(
      "x-prism-voice-pacing",
      "kokoro-punctuation-v1",
    );
  }
  setVoicePronunciationHeaders(args.response, args.pronunciation);
  setVoiceSpeechprintHeaders(args.response, args.speechprint);
  if (args.localEngine) {
    args.response.setHeader(
      "x-prism-local-voice-engine",
      args.localEngine.resolved,
    );
    args.response.setHeader("x-prism-voice-model", PRISM_INSTANT_VOICE_MODEL_ID);
    args.response.setHeader(
      "x-prism-voice-model-sha256",
      PRISM_INSTANT_VOICE_MODEL_SHA256,
    );
    if (args.localEngine.notice) {
      args.response.setHeader(
        "x-prism-voice-notice",
        encodeURIComponent(args.localEngine.notice),
      );
    }
  }
  if (hasVocalActions) {
    args.response.setHeader(
      "x-prism-voice-segments",
      String(streamItems.length),
    );
  }
  const writeSpeechChunk = (wave: Buffer, item: Extract<(typeof streamItems)[number], { kind: "speech" }>, index: number) => {
    args.response.write(
      `${JSON.stringify({
        index,
        ...(hasVocalActions ? { kind: "speech" } : {}),
        characterCount: item.text.length + (index > 0 ? 1 : 0),
        text: item.text,
        // Always include source spans so the client can lock mouth/text to each
        // Kokoro clause instead of inventing a full-utterance weight clock.
        sourceStart: item.sourceStart,
        sourceEnd: item.sourceEnd,
        audioBase64: wave.toString("base64"),
      })}\n`,
    );
  };
  const writeActionChunk = (
    item: Extract<(typeof streamItems)[number], { kind: "vocal-action" }>,
    index: number,
  ) => {
    args.response.write(
      `${JSON.stringify({
        index,
        kind: "vocal-action",
        characterCount: 0,
        action: item.action,
        modifiers: item.modifiers,
        authoredText: item.authoredText,
        sourceStart: item.sourceStart,
        sourceEnd: item.sourceEnd,
      })}\n`,
    );
  };

  for (let index = 0; index < streamItems.length; index += 1) {
    if (args.signal.aborted || args.response.destroyed) return;
    const item = streamItems[index]!;
    if (item.kind === "vocal-action") {
      writeActionChunk(item, index);
      continue;
    }
    const generatedWave = index === 0 && firstWave
      ? firstWave
      : await generate(item.text);
    if (args.signal.aborted || args.response.destroyed) return;
    // Only server-tagged Instant/Kokoro streams reach this branch. Preserve
    // natural outer silence for the utterance, but remove duplicated generator
    // silence at every internal speech edge before the client's restrained gap.
    const wave = args.punctuationPacing === true
      ? trimPcmWaveChunkJoinSilence(generatedWave, {
          trimLeading: index !== firstSpeechItemIndex,
          trimTrailing: index !== lastSpeechItemIndex,
        })
      : generatedWave;
    writeSpeechChunk(wave, item, index);
  }
  args.response.end();
}
