function route(
  method: string,
  pathTemplate: string,
  handler: RouteDefinition["handler"],
): RouteDefinition {
  const keys: string[] = [];
  const pattern = new RegExp(
    "^" +
      pathTemplate
        .replace(/\//g, "\\/")
        .replace(/:([A-Za-z0-9_]+)/g, (_full, key: string) => {
          keys.push(key);
          return "([^/]+)";
        }) +
      "$",
  );
  return { method, pattern, keys, handler };
}

function parseParams(
  definition: RouteDefinition,
  pathname: string,
): Record<string, string> {
  const match = pathname.match(definition.pattern);
  if (!match) {
    return {};
  }
  return definition.keys.reduce<Record<string, string>>((acc, key, index) => {
    acc[key] = decodeURIComponent(match[index + 1]);
    return acc;
  }, {});
}

function getSessionToken(ctx: RequestContext): string | null {
  return resolveSessionToken(ctx.req.headers, config.sessionCookieName);
}

function requireAuth(ctx: RequestContext): string {
  const sessionToken = getSessionToken(ctx);
  const session = requireValidSession(db, sessionToken);
  ctx.sessionToken = session.token;
  ctx.userId = session.userId;
  touchUserActivity(session.userId);
  return session.userId;
}

function asTurnPreparationHttpError(error: unknown): never {
  if (!(error instanceof TurnPreparationError)) throw error;
  const status = error.code === "not_found" ? 404 : error.code === "expired" ? 410 : 409;
  throw new HttpError(status, error.message);
}

function invalidateTurnPreparation(
  userId: string,
  surface: "coffee" | "signal" | "debate",
  sessionId: string,
  reason: string,
): void {
  turnPreparationRegistry.discardSession(userId, surface, sessionId, reason);
}

