function readReplaySurface(value: unknown): ReplaySurfaceV1 | null {
  return value === "signal" || value === "coffee" ? value : null;
}

function readPresenceBeatSurface(value: unknown) {
  return value === "chat" ||
    value === "zen" ||
    value === "sandbox" ||
    value === "coffee" ||
    value === "signal" ||
    value === "debate"
    ? value
    : null;
}

function readReplayStatus(value: unknown): ReplayRecordingStatusV1 | null {
  return value === "collecting" ||
    value === "queued" ||
    value === "preparing_audio" ||
    value === "rendering" ||
    value === "ready" ||
    value === "ready_with_warnings" ||
    value === "failed"
    ? value
    : null;
}

function readReplayRenderToken(ctx: RequestContext): string {
  const raw = ctx.req.headers["x-prism-replay-token"];
  const value = (Array.isArray(raw) ? raw[0] : raw)?.trim() ?? "";
  if (!/^[a-f0-9]{36}$/u.test(value)) {
    throw new HttpError(409, "Replay render lease is missing or invalid.");
  }
  return value;
}

function streamReplayFile(
  ctx: RequestContext,
  file: { absolutePath: string; contentType: string; sizeBytes: number },
  options: { attachmentName?: string; range?: boolean } = {},
): void {
  const rangeHeader = options.range ? ctx.req.headers.range : undefined;
  let start = 0;
  let end = Math.max(0, file.sizeBytes - 1);
  if (typeof rangeHeader === "string") {
    const match = rangeHeader.match(/^bytes=(\d*)-(\d*)$/u);
    if (!match) {
      ctx.res.statusCode = 416;
      ctx.res.setHeader("content-range", `bytes */${file.sizeBytes}`);
      ctx.res.end();
      return;
    }
    const requestedStart = match[1] ? Number(match[1]) : null;
    const requestedEnd = match[2] ? Number(match[2]) : null;
    if (requestedStart === null && requestedEnd !== null) {
      start = Math.max(0, file.sizeBytes - requestedEnd);
    } else if (requestedStart !== null) {
      start = requestedStart;
    }
    if (requestedEnd !== null && requestedStart !== null) end = requestedEnd;
    end = Math.min(end, file.sizeBytes - 1);
    if (
      !Number.isSafeInteger(start) ||
      !Number.isSafeInteger(end) ||
      start < 0 ||
      start > end ||
      start >= file.sizeBytes
    ) {
      ctx.res.statusCode = 416;
      ctx.res.setHeader("content-range", `bytes */${file.sizeBytes}`);
      ctx.res.end();
      return;
    }
    ctx.res.statusCode = 206;
    ctx.res.setHeader(
      "content-range",
      `bytes ${start}-${end}/${file.sizeBytes}`,
    );
  } else {
    ctx.res.statusCode = 200;
  }
  ctx.res.setHeader("content-type", file.contentType);
  ctx.res.setHeader("content-length", String(end - start + 1));
  ctx.res.setHeader("cache-control", "private, no-store");
  if (options.range) ctx.res.setHeader("accept-ranges", "bytes");
  if (options.attachmentName) {
    ctx.res.setHeader(
      "content-disposition",
      `attachment; filename="${options.attachmentName.replace(/[^a-zA-Z0-9._-]/gu, "-")}"`,
    );
  }
  const stream = createReadStream(file.absolutePath, { start, end });
  stream.on("error", () => {
    if (!ctx.res.headersSent) {
      json(ctx.res, 404, { ok: false, error: "Replay media is unavailable." });
    } else if (!ctx.res.writableEnded) {
      ctx.res.destroy();
    }
  });
  stream.pipe(ctx.res);
}

function isLoopbackRequest(ctx: RequestContext): boolean {
  return isLoopbackAddress(ctx.req.socket.remoteAddress);
}

function requireLoopback(ctx: RequestContext): void {
  if (!isLoopbackRequest(ctx)) {
    throw new Error("Local pairing codes can only be generated on this Mac.");
  }
}

/**
 * Whether the local-network toggle may be changed by this request.
 *
 * The guarantee "only the host machine can widen exposure" survives the web
 * reverse-proxy: we never trust client-supplied forwarding headers, only the
 * direct socket peer plus a server-set `x-prism-web-origin` marker that the web
 * proxy stamps from its OWN bind mode (and strips any client copy of). A LAN
 * device cannot reach the API over loopback, and once the web front-end is
 * itself LAN-exposed we can no longer prove a proxied request is local, so the
 * toggle becomes host-only (native app / host CLI) until switched off.
 */
function canEditNetworkAccess(ctx: RequestContext): boolean {
  const header = ctx.req.headers["x-prism-web-origin"];
  return decideCanEditNetworkAccess({
    peerAddress: ctx.req.socket.remoteAddress,
    webOrigin: Array.isArray(header) ? header[0] : header,
    managedByEnv: lanAccessManagedByEnv(),
  });
}

function requireLocalDeveloperRequest(ctx: RequestContext): void {
  if (!isLoopbackRequest(ctx)) {
    throw new Error(
      "Developer server commands can only be requested from this computer.",
    );
  }
}

function isNodeWatchMode(): boolean {
  return process.execArgv.some(
    (arg) =>
      arg === "--watch" ||
      arg.startsWith("--watch=") ||
      arg === "--watch-path" ||
      arg.startsWith("--watch-path="),
  );
}

function scheduleApiWatchRestart(): boolean {
  if (!isNodeWatchMode()) {
    return false;
  }
  setTimeout(() => {
    try {
      const serverEntryPath = fileURLToPath(import.meta.url);
      const now = new Date();
      utimesSync(serverEntryPath, now, now);
    } catch (error) {
      console.error("Failed to trigger Prism API watch restart.", error);
    }
  }, 150).unref();
  return true;
}

function getOrCreateLocalOwnerUser(): string {
  const existing = db
    .prepare("SELECT id FROM users WHERE email = ?")
    .get(LOCAL_OWNER_USERNAME) as { id?: string } | undefined;
  if (existing?.id) {
    touchUserActivity(existing.id);
    return existing.id;
  }

  const userId = randomId(12);
  const salt = randomId(8);
  const passwordHash = hashPassword(randomId(32), salt);
  const userKey = Buffer.from(randomId(32), "hex");
  const wrappedUserKey = encryptText(userKey.toString("base64"), masterKey);
  const createdAt = new Date().toISOString();

  db.prepare(
    `
    INSERT INTO users (
      id, email, display_name, password_hash, password_salt,
      wrapped_user_key, wrapped_user_key_iv, wrapped_user_key_tag,
      theme, preferred_provider, auto_memory,
      prism_default_bot_face_mouth_coffee_pucker,
      english_voice_engine, created_at, last_active_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'system', 'local', 1, ?, 'builtin', ?, ?)
  `,
  ).run(
    userId,
    LOCAL_OWNER_USERNAME,
    LOCAL_OWNER_DISPLAY_NAME,
    passwordHash,
    salt,
    wrappedUserKey.ciphertext,
    wrappedUserKey.iv,
    wrappedUserKey.tag,
    DEFAULT_BOT_FACE_MOUTH_COFFEE_PUCKER ? 1 : 0,
    createdAt,
    createdAt,
  );
  createPendingLivingShellAccountProgress(db, userId, createdAt);

  return userId;
}

