function readProvider(value: unknown): ProviderName | undefined {
  return value === "local" || value === "openai" || value === "anthropic"
    ? value
    : undefined;
}

function frozenDebateModelOverride(session: {
  model: string;
  modelSelectionKind?: "auto" | "fixed";
}): string {
  // Auto chooses once when the Debate is created. Every later generation,
  // including Spectator bake, keeps that concrete primary model.
  return session.model;
}

function debateAutoRoutingContext(
  session: Pick<
    ReturnType<typeof getDebateSession>,
    | "motion"
    | "evidence"
    | "stepKey"
    | "events"
    | "lastReasoningEffort"
    | "lastTurbo"
    | "latestAutoRoute"
  >,
): AutoRoutingContextV1 & {
  frozenReasoningEffort?: ProviderReasoningEffort;
  frozenTurbo?: boolean;
} {
  const evidenceSources = session.evidence.sources.flatMap((source) => [
    source.title,
    source.snippet,
  ]);
  const exhibits = (session.evidence.exhibits ?? []).flatMap((exhibit) => [
    exhibit.title,
    exhibit.observation,
  ]);
  const inputText = [
    session.motion.title ?? "",
    session.motion.motion,
    session.motion.forSide.brief,
    session.motion.againstSide.brief,
    session.evidence.notes,
    ...evidenceSources,
    ...exhibits,
    ...session.events.map((event) => event.content),
  ]
    .filter(Boolean)
    .join("\n");
  const shortTurn = /(?:interject|objection|gavel|reaction)/u.test(
    session.stepKey,
  );

  return {
    surface: "debate",
    inputText,
    // Account for the frozen personas and procedural instructions that wrap
    // the visible record in every Debate generation prompt.
    inputTokens: 1_200 + Math.ceil(inputText.length / 4),
    outputTokens: shortTurn ? 900 : 2_400,
    structuredOutput: true,
    highStakes: true,
    ...(session.lastReasoningEffort
      ? { frozenReasoningEffort: session.lastReasoningEffort }
      : session.latestAutoRoute?.reasoningEffort
        ? { frozenReasoningEffort: session.latestAutoRoute.reasoningEffort }
        : {}),
    ...(typeof session.lastTurbo === "boolean"
      ? { frozenTurbo: session.lastTurbo }
      : {}),
  };
}

async function debateAiRuntimeForUser(
  userId: string,
  requestedProvider: unknown,
  requestedModelOverride?: unknown,
  requestedResponseMode?: unknown,
  requestedFrozenChain?: unknown,
  requestedFrozenCandidates?: unknown,
  requestedRoutingContext?: AutoRoutingContextV1 & {
    frozenReasoningEffort?: ProviderReasoningEffort;
    frozenTurbo?: boolean;
  },
): Promise<DebateAiRuntime> {
  const user = getUserRow(userId);
  const requestedProviderName = readProvider(requestedProvider);
  const legacyDefaultLane =
    requestedProviderName === "local" ||
    (!requestedProviderName && user.preferred_provider === "local")
      ? "local"
      : "online";
  const requestedMode = normalizeResponseMode(
    requestedResponseMode,
    legacyDefaultLane,
  );
  const responseLane =
    requestedMode === "auto" ? legacyDefaultLane : requestedMode;
  const preferredProvider: ProviderName =
    responseLane === "local"
      ? "local"
      : requestedProviderName && requestedProviderName !== "local"
        ? requestedProviderName
        : user.preferred_provider === "anthropic"
          ? "anthropic"
          : "openai";
  const modelOverride = readModelOverride(requestedModelOverride);
  const userKey = responseLane === "online" ? decryptUserKey(userId) : null;
  const openAiApiKey =
    responseLane === "online"
      ? (getOpenAiApiKeyForUser(userId, userKey!) ?? config.openAiApiKey)
      : undefined;
  const anthropicApiKey =
    responseLane === "online"
      ? (getAnthropicApiKeyForUser(userId, userKey!) ?? config.anthropicApiKey)
      : undefined;
  const catalog = await buildModelCatalog(
    openAiApiKey,
    user.secondary_ollama_host,
    anthropicApiKey,
  );
  const frozenCandidateKeys = new Set(
    (Array.isArray(requestedFrozenCandidates)
      ? requestedFrozenCandidates
          .map(normalizeAutoFallbackModelRef)
          .filter((entry): entry is AutoFallbackModelRef => entry !== null)
      : []
    ).map((entry) => `${entry.provider}:${entry.model.toLowerCase()}`),
  );
  const routingCatalog =
    frozenCandidateKeys.size === 0
      ? catalog
      : {
          local: catalog.local.filter((entry) =>
            frozenCandidateKeys.has(`local:${entry.id.toLowerCase()}`),
          ),
          online: catalog.online.filter((entry) =>
            frozenCandidateKeys.has(
              `${entry.provider === "anthropic" ? "anthropic" : "openai"}:${entry.id.toLowerCase()}`,
            ),
          ),
        };
  const hiddenModelIds = parseHiddenBotModelIds(user.hidden_bot_model_ids);
  const frozenReasoningEffort = normalizeProviderReasoningEffort(
    requestedRoutingContext?.frozenReasoningEffort,
  );
  const frozenTurbo = requestedRoutingContext?.frozenTurbo;
  const resolvedPrimary = resolveAutoModel({
    provider: preferredProvider,
    lane: responseLane,
    explicitModelOverride: modelOverride,
    hiddenModelIds,
    catalog: routingCatalog,
    onlineAutoProviderBias: clampOnlineAutoProviderBias(
      user.online_auto_provider_bias,
    ),
    routingContext: {
      surface: "debate",
      structuredOutput: true,
      highStakes: true,
      outputTokens: 2_400,
      ...requestedRoutingContext,
    },
  });
  const primaryEffort =
    frozenReasoningEffort !== "auto"
      ? frozenReasoningEffort
      : resolvedPrimary.autoRoute?.reasoningEffort ??
        resolveUserModelReasoningEffort(db, {
          userId,
          provider: resolvedPrimary.provider,
          modelId: resolvedPrimary.model,
        });
  const localModel =
    resolvedPrimary.provider === "local"
      ? resolvedPrimary.model
      : routingCatalog.local[0]?.id ??
        defaultModelIdForProvider("local");
  const deepSimulatedEffort =
    user.experimental_all_model_effort_enabled === 1;
  const local: DebateAiRuntime["local"] = {
    provider: providerFactoryOverride(
      "local",
      undefined,
      user.secondary_ollama_host,
      undefined,
    ),
    providerName: "local",
    model: localModel,
    turbo: frozenTurbo === true,
    deepSimulatedEffort,
    reasoningEffort:
      resolvedPrimary.provider === "local"
        ? primaryEffort
        : resolveUserModelReasoningEffort(db, {
            userId,
            provider: "local",
            modelId: localModel,
          }),
  };
  const auxiliary = auxiliaryProviderFactoryOverride(
    user.prism_default_llm_model,
    dualOllamaWorkloadOptions(user),
  );
  const onlineLane = (
    providerName: "openai" | "anthropic",
    model: string,
    reasoningEffort?: ProviderReasoningEffort,
  ): NonNullable<DebateAiRuntime["online"]> => {
    const apiKey =
      providerName === "anthropic" ? anthropicApiKey : openAiApiKey;
    return {
      provider: providerFactoryOverride(
        providerName,
        providerName === "openai" ? apiKey : undefined,
        user.secondary_ollama_host,
        providerName === "anthropic" ? apiKey : undefined,
      ),
      providerName,
      model,
      turbo:
        typeof frozenTurbo === "boolean"
          ? frozenTurbo
          : resolveUserModelTurboMode(db, {
              userId,
              provider: providerName,
              modelId: model,
            }),
      deepSimulatedEffort,
      reasoningEffort:
        reasoningEffort ??
        resolveUserModelReasoningEffort(db, {
          userId,
          provider: providerName,
          modelId: model,
        }),
      available: providerFactoryOverride !== selectProvider || Boolean(apiKey),
    };
  };
  const primary =
    resolvedPrimary.provider === "local"
      ? { ...local, reasoningEffort: primaryEffort }
      : onlineLane(
          resolvedPrimary.provider,
          resolvedPrimary.model,
          primaryEffort,
        );
  const hasFrozenChain = Array.isArray(requestedFrozenChain);
  const frozenChain = hasFrozenChain
    ? requestedFrozenChain
        .map(normalizeAutoFallbackModelRef)
        .filter((entry): entry is AutoFallbackModelRef => entry !== null)
    : [];
  const configuredChain = parseStoredAutoFallbackChain(
    user.auto_fallback_chain,
  );
  const primaryRef: AutoFallbackModelRef = {
    provider: primary.providerName,
    model: primary.model,
  };
  const frozenFallbacks =
    frozenChain.length > 1
      ? frozenChain.slice(1).filter(
          (entry) =>
            (entry.provider === "local" ? "local" : "online") === responseLane,
        )
      : [];
  const resolvedChain =
    hasFrozenChain
      ? [primaryRef, ...frozenFallbacks]
      : (autoFallbackResolvedChain(primaryRef, configuredChain) ?? [primaryRef]);
  const seen = new Set<string>();
  const lanes = resolvedChain
    .filter((entry) => {
      const key = `${entry.provider}:${entry.model.toLowerCase()}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .map((entry, index) =>
      entry.provider === "local"
        ? {
            ...local,
            model: entry.model,
            reasoningEffort:
              index === 0
                ? primaryEffort
                : ("none" satisfies ReasoningEffort),
          }
        : onlineLane(
            entry.provider,
            entry.model,
            index === 0
              ? primaryEffort
              : ("none" satisfies ReasoningEffort),
          ),
    );
  return {
    local,
    ...(primary.providerName !== "local" ? { online: primary } : {}),
    auxiliary,
    preferredProvider: primary.providerName,
    responseMode: responseLane,
    lanes,
    modelSelectionKind: resolvedPrimary.autoRoute ? "auto" : "fixed",
    autoCandidateAllowlist: (
      responseLane === "local"
        ? routingCatalog.local.map((entry) => ({
            provider: "local" as const,
            model: entry.id,
          }))
        : routingCatalog.online.map((entry) => ({
            provider:
              entry.provider === "anthropic"
                ? ("anthropic" as const)
                : ("openai" as const),
            model: entry.id,
          }))
    ).filter((entry) => !hiddenModelIds.includes(entry.model)),
    ...(resolvedPrimary.autoRoute
      ? { autoRoute: resolvedPrimary.autoRoute }
      : {}),
  };
}

function readResolvedPowerTheme(value: unknown): "light" | "dark" | undefined {
  return value === "light" || value === "dark" ? value : undefined;
}

function readApiKeyValidationProvider(
  value: unknown,
): ApiKeyValidationProvider {
  if (
    value === "openai" ||
    value === "anthropic" ||
    value === "elevenlabs" ||
    value === "brave"
  ) {
    return value;
  }
  throw new Error("provider is required.");
}

function sanitizeApiKeyForProvider(
  provider: ApiKeyValidationProvider,
  value: string,
): string {
  if (provider === "anthropic") return sanitizeAnthropicKeyInput(value);
  if (provider === "elevenlabs") return sanitizeElevenLabsKeyInput(value);
  if (provider === "brave") return sanitizeBraveSearchKeyInput(value);
  return sanitizeOpenAiKeyInput(value);
}

function readString(value: unknown, fieldName: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new Error(`${fieldName} is required.`);
  }
  return value.trim();
}

function readOptionalString(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

const BOT_TOP_P_DEFAULT = 1;
const BOT_TOP_K_DEFAULT = 40;
const BOT_REPETITION_PENALTY_DEFAULT = 1.1;
const BOT_TEMPERATURE_DEFAULT = 0.7;
const BOT_TEMPERATURE_MIN = 0;
const BOT_TEMPERATURE_MAX = 1.2;
const BOT_REPLY_LENGTH_DEFAULT_TOKENS = 2048;

function normalizeBotTemperature(value: unknown): number {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return BOT_TEMPERATURE_DEFAULT;
  }
  return Number(
    Math.min(BOT_TEMPERATURE_MAX, Math.max(BOT_TEMPERATURE_MIN, value)).toFixed(
      2,
    ),
  );
}

function normalizeBotMaxTokens(value: unknown): number {
  if (typeof value !== "number" || !Number.isFinite(value) || value <= 0) {
    return BOT_REPLY_LENGTH_DEFAULT_TOKENS;
  }
  return Math.round(value);
}

function normalizeBotTopP(value: unknown): number {
  if (typeof value !== "number" || !Number.isFinite(value))
    return BOT_TOP_P_DEFAULT;
  return Number(Math.min(1, Math.max(0, value)).toFixed(2));
}

function normalizeBotTopK(value: unknown): number {
  if (typeof value !== "number" || !Number.isFinite(value))
    return BOT_TOP_K_DEFAULT;
  return Math.max(0, Math.floor(value));
}

function normalizeBotRepetitionPenalty(value: unknown): number {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return BOT_REPETITION_PENALTY_DEFAULT;
  }
  return Number(Math.min(2, Math.max(0.5, value)).toFixed(2));
}

function readManualChatTool(value: unknown): ManualChatToolRequest | undefined {
  if (value === undefined || value === null) return undefined;
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new HttpError(400, "manualTool must be an object.");
  }
  const record = value as Record<string, unknown>;
  const rawName =
    typeof record.name === "string" ? record.name.trim().toLowerCase() : "";
  if (
    rawName === "websearch" ||
    rawName === "web-search" ||
    rawName === "web_search"
  ) {
    const query = readOptionalString(record.query);
    return {
      name: "webSearch",
      ...(query ? { query: query.slice(0, 500) } : {}),
    };
  }
  if (
    rawName === "imagegen" ||
    rawName === "image-gen" ||
    rawName === "image_gen"
  ) {
    const prompt = readOptionalString(record.prompt);
    return {
      name: "imageGen",
      ...(prompt ? { prompt: prompt.slice(0, 1000) } : {}),
    };
  }
  if (
    rawName === "askquestion" ||
    rawName === "ask-question" ||
    rawName === "ask_question"
  ) {
    const question = readOptionalString(record.question);
    const options = Array.isArray(record.options)
      ? record.options
          .map((option) =>
            typeof option === "string"
              ? option.trim().replace(/\s+/g, " ").slice(0, 80)
              : "",
          )
          .filter((option) => option.length > 0)
          .slice(0, 4)
      : undefined;
    return {
      name: "askQuestion",
      ...(question ? { question: question.slice(0, 240) } : {}),
      ...(options && options.length > 0 ? { options } : {}),
    };
  }
  throw new HttpError(
    400,
    "manualTool.name must be webSearch, imageGen, or askQuestion.",
  );
}

function readModelOverride(value: unknown): string | null {
  const model = readOptionalString(value);
  // Legacy text selections used `disabled` as a synthetic model. Text lanes
  // can no longer be disabled, so importing or replaying that value means Auto.
  if (model && isDisabledModelChoice(model)) return null;
  return model;
}

function readCoffeeSessionSpeakerModel(value: unknown): string | null {
  const model = readModelOverride(value);
  return model?.toLowerCase() === "auto" ? null : model;
}

/**
 * Resolves one text generation against the selected privacy lane. Legacy AUTO
 * inputs are accepted only as reads and collapse to the lane implied by the
 * frozen/requested provider; new callers receive a concrete binary lane.
 */
type ContextualRequestedReasoningEffort =
  | import("@localai/shared").ProviderReasoningEffort
  | undefined;

type ContextualResolvedReasoningEffort<
  TRequested extends ContextualRequestedReasoningEffort,
> = Extract<TRequested, "max"> extends never
  ? import("@localai/shared").ModelReasoningEffortPreference | undefined
  : Exclude<import("@localai/shared").ProviderReasoningEffort, "auto"> | undefined;

async function contextualTextRuntimeForUser<
  TRequested extends ContextualRequestedReasoningEffort = undefined,
>(args: {
  userId: string;
  user: UserDbRow;
  requestedProvider?: unknown;
  requestedResponseMode?: unknown;
  modelOverride?: unknown;
  requestedReasoningEffort?: TRequested;
  requestedTurbo?: unknown;
  frozenCandidateAllowlist?: unknown;
  frozenFallbackChain?: unknown;
  routingContext: AutoRoutingContextV1;
}) {
  const requestedProvider = readProvider(args.requestedProvider);
  const legacyDefaultLane =
    requestedProvider === "local" ||
    (!requestedProvider && args.user.preferred_provider === "local")
      ? "local"
      : "online";
  const normalizedMode = normalizeResponseMode(
    args.requestedResponseMode,
    legacyDefaultLane,
  );
  const responseMode =
    normalizedMode === "auto" ? legacyDefaultLane : normalizedMode;
  const primaryProvider: ProviderName =
    responseMode === "local"
      ? "local"
      : requestedProvider && requestedProvider !== "local"
        ? requestedProvider
        : args.user.preferred_provider === "anthropic"
          ? "anthropic"
          : "openai";
  const userKey = responseMode === "online" ? decryptUserKey(args.userId) : null;
  const openAiApiKey =
    responseMode === "online"
      ? (getOpenAiApiKeyForUser(args.userId, userKey!) ?? config.openAiApiKey)
      : undefined;
  const anthropicApiKey =
    responseMode === "online"
      ? (getAnthropicApiKeyForUser(args.userId, userKey!) ??
        config.anthropicApiKey)
      : undefined;
  const catalog = await buildModelCatalog(
    openAiApiKey,
    args.user.secondary_ollama_host,
    anthropicApiKey,
  );
  const frozenCandidateKeys = new Set(
    (Array.isArray(args.frozenCandidateAllowlist)
      ? args.frozenCandidateAllowlist
          .map(normalizeAutoFallbackModelRef)
          .filter((entry): entry is AutoFallbackModelRef => entry !== null)
      : []
    ).map((entry) => `${entry.provider}:${entry.model.toLowerCase()}`),
  );
  const routingCatalog =
    frozenCandidateKeys.size === 0
      ? catalog
      : {
          ...catalog,
          local: catalog.local.filter((entry) =>
            frozenCandidateKeys.has(`local:${entry.id.toLowerCase()}`),
          ),
          online: catalog.online.filter((entry) =>
            frozenCandidateKeys.has(
              `${entry.provider === "anthropic" ? "anthropic" : "openai"}:${entry.id.toLowerCase()}`,
            ),
          ),
        };
  const hiddenModelIds = parseHiddenBotModelIds(args.user.hidden_bot_model_ids);
  const hiddenModels = new Set(hiddenModelIds);
  const explicitModelOverride = readCoffeeSessionSpeakerModel(
    args.modelOverride,
  );
  const resolved = resolveAutoModel({
    provider: primaryProvider,
    lane: responseMode,
    explicitModelOverride,
    hiddenModelIds,
    catalog: routingCatalog,
    onlineAutoProviderBias: clampOnlineAutoProviderBias(
      args.user.online_auto_provider_bias,
    ),
    routingContext: {
      ...args.routingContext,
      simulatedEffortEnabled: true,
    },
  });
  const storedReasoningEffort = resolveUserModelReasoningEffort(db, {
      userId: args.userId,
      provider: resolved.provider,
      modelId: resolved.model,
      simulatedEffortEnabled: true,
    });
  const requestedProviderReasoningEffort = normalizeProviderReasoningEffort(
    args.requestedReasoningEffort,
  );
  const maxReasoningEffortRequested =
    requestedProviderReasoningEffort === "max";
  if (maxReasoningEffortRequested) {
    const capability = resolveModelReasoningEffortCapability({
      provider: resolved.provider,
      modelId: resolved.model,
      simulatedEffortEnabled: false,
    });
    if (
      !explicitModelOverride ||
      resolved.autoRoute ||
      storedReasoningEffort !== "xhigh" ||
      capability.mode !== "native" ||
      !capability.supportsMax
    ) {
      throw new HttpError(
        400,
        "Max reasoning requires an explicitly selected compatible native model with saved Effort set to XHigh.",
      );
    }
  }
  const reasoningEffort = (
    maxReasoningEffortRequested
      ? "max"
      : resolved.autoRoute?.reasoningEffort ??
        normalizeModelReasoningEffortPreference(
          args.requestedReasoningEffort,
        ) ??
        storedReasoningEffort
  ) as ContextualResolvedReasoningEffort<TRequested>;
  const candidateAllowlist = (
    responseMode === "local" ? routingCatalog.local : routingCatalog.online
  )
    .filter((entry) => !hiddenModels.has(entry.id))
    .map((entry): AutoFallbackModelRef => ({
      provider:
        entry.provider === "anthropic"
          ? "anthropic"
          : entry.provider === "local"
            ? "local"
            : "openai",
      model: entry.id,
    }));
  const frozenFallbacks =
    args.frozenFallbackChain !== undefined
      ? (Array.isArray(args.frozenFallbackChain)
          ? args.frozenFallbackChain
              .map(normalizeAutoFallbackModelRef)
              .filter(
                (entry): entry is AutoFallbackModelRef =>
                  entry !== null &&
                  (entry.provider === "local" ? "local" : "online") ===
                    responseMode,
              )
          : [])
      : null;
  return {
    responseMode,
    provider: resolved.provider,
    model: resolved.model,
    reasoningEffort,
    turbo:
      typeof args.requestedTurbo === "boolean"
        ? args.requestedTurbo
        : resolveUserModelTurboMode(db, {
            userId: args.userId,
            provider: resolved.provider,
            modelId: resolved.model,
          }),
    autoRoute: resolved.autoRoute,
    candidateAllowlist,
    openAiApiKey,
    anthropicApiKey,
    autoFallbackChain:
      frozenFallbacks !== null
        ? frozenFallbacks.length > 0
          ? { v: 1 as const, fallbacks: frozenFallbacks }
          : null
        : parseStoredAutoFallbackChain(args.user.auto_fallback_chain),
  };
}

async function contextualSignalRuntimeForEpisode(args: {
  userId: string;
  user: UserDbRow;
  episode: ReturnType<typeof getBotcastEpisode>;
}) {
  const snapshot = botcastRoutingSnapshot(args.episode);
  const autoSelected = snapshot?.modelSelectionKind === "auto";
  return contextualTextRuntimeForUser({
    userId: args.userId,
    user: args.user,
    requestedProvider: args.episode.provider,
    requestedResponseMode:
      args.episode.provider === "local" ? "local" : "online",
    modelOverride: autoSelected ? null : args.episode.model,
    ...(snapshot
      ? { frozenCandidateAllowlist: snapshot.candidateAllowlist }
      : {}),
    // Legacy sessions had no frozen fallback provenance; keep them to their
    // recorded primary instead of applying today's account configuration.
    frozenFallbackChain: snapshot?.fallbackChain ?? [],
    routingContext: {
      surface: "signal",
      inputText: [
        args.episode.topic,
        args.episode.producerBrief,
        ...args.episode.messages.slice(-12).map((message) => message.content),
      ].join("\n"),
      outputTokens: 900,
      highStakes: true,
    },
  });
}

function readCoffeeTeamCreateInput(value: unknown):
  | {
      left?: { name?: unknown; description?: unknown };
      right?: { name?: unknown; description?: unknown };
      assignments?: unknown;
      playerTeamId?: unknown;
    }
  | undefined {
  if (!value || typeof value !== "object" || Array.isArray(value))
    return undefined;
  const record = value as Record<string, unknown>;
  const left =
    record.left &&
    typeof record.left === "object" &&
    !Array.isArray(record.left)
      ? (record.left as { name?: unknown; description?: unknown })
      : undefined;
  const right =
    record.right &&
    typeof record.right === "object" &&
    !Array.isArray(record.right)
      ? (record.right as { name?: unknown; description?: unknown })
      : undefined;
  return {
    left,
    right,
    assignments: record.assignments,
    playerTeamId: record.playerTeamId,
  };
}

function readPrismMoodMode(value: unknown): PrismMoodMode {
  if (value === "chat") return "zen";
  return value === "coffee" || value === "sandbox" || value === "zen"
    ? value
    : "zen";
}

function readPrismInterruption(
  value: unknown,
): PrismMoodInterruptionInput | undefined {
  if (!value || typeof value !== "object") return undefined;
  const record = value as Record<string, unknown>;
  const kind =
    record.kind === "pending_reply" ? "pending_reply" : "assistant_reveal";
  return {
    kind,
    ...(typeof record.assistantMessageId === "string" &&
    record.assistantMessageId.trim().length > 0
      ? { assistantMessageId: record.assistantMessageId.trim() }
      : {}),
    ...(typeof record.visibleTokenCount === "number" &&
    Number.isFinite(record.visibleTokenCount)
      ? { visibleTokenCount: Math.max(1, Math.floor(record.visibleTokenCount)) }
      : {}),
    ...(typeof record.totalTokenCount === "number" &&
    Number.isFinite(record.totalTokenCount)
      ? { totalTokenCount: Math.max(1, Math.floor(record.totalTokenCount)) }
      : {}),
    ...(typeof record.interruptedContent === "string" &&
    record.interruptedContent.trim().length > 0
      ? { interruptedContent: record.interruptedContent.trim() }
      : {}),
  };
}

function readAssistantInterruptionReaction(
  value: unknown,
): AssistantInterruptionReactionInput | undefined {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return undefined;
  }
  const record = value as Record<string, unknown>;
  if (record.source !== "shh") return undefined;
  const assistantMessageId =
    typeof record.assistantMessageId === "string"
      ? record.assistantMessageId.trim().slice(0, 120)
      : "";
  const interruptedContent =
    typeof record.interruptedContent === "string"
      ? record.interruptedContent.trim().slice(0, 12_000)
      : "";
  const clientTurnId =
    typeof record.clientTurnId === "string"
      ? record.clientTurnId.trim().slice(0, 120)
      : "";
  if (!assistantMessageId || !interruptedContent || !clientTurnId) {
    return undefined;
  }
  const activeBotId =
    typeof record.activeBotId === "string" && record.activeBotId.trim()
      ? record.activeBotId.trim()
      : null;
  return {
    source: "shh",
    activeBotId,
    assistantMessageId,
    interruptedContent,
    clientTurnId,
  };
}

type StoredAssistantInterruptionState = {
  v: 1;
  source: "shh";
  interruptedContent: string;
  status:
    | "cutoff"
    | "reaction_pending"
    | "reaction_failed"
    | "reaction_complete";
  updatedAt: string;
  clientTurnId?: string;
  claimId?: string;
  reactionMessageId?: string;
};

function readToolPayloadRecord(value: string | null | undefined): Record<string, unknown> | null {
  if (!value) return null;
  try {
    const parsed = JSON.parse(value) as unknown;
    return parsed && typeof parsed === "object" && !Array.isArray(parsed)
      ? (parsed as Record<string, unknown>)
      : null;
  } catch {
    return null;
  }
}

function readStoredAssistantInterruptionState(
  toolPayload: string | null | undefined,
): StoredAssistantInterruptionState | null {
  const root = readToolPayloadRecord(toolPayload);
  const value = root?.assistantInterruption;
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const record = value as Record<string, unknown>;
  if (record.v !== 1 || record.source !== "shh") return null;
  const interruptedContent =
    typeof record.interruptedContent === "string"
      ? record.interruptedContent.trim()
      : "";
  const status =
    record.status === "cutoff" ||
    record.status === "reaction_pending" ||
    record.status === "reaction_failed" ||
    record.status === "reaction_complete"
      ? record.status
      : null;
  const updatedAt =
    typeof record.updatedAt === "string" ? record.updatedAt : "";
  if (!interruptedContent || !status || !updatedAt) return null;
  return {
    v: 1,
    source: "shh",
    interruptedContent,
    status,
    updatedAt,
    ...(typeof record.clientTurnId === "string" && record.clientTurnId
      ? { clientTurnId: record.clientTurnId }
      : {}),
    ...(typeof record.claimId === "string" && record.claimId
      ? { claimId: record.claimId }
      : {}),
    ...(typeof record.reactionMessageId === "string" &&
    record.reactionMessageId
      ? { reactionMessageId: record.reactionMessageId }
      : {}),
  };
}

function serializeStoredAssistantInterruptionState(
  state: StoredAssistantInterruptionState,
): string {
  return JSON.stringify({ v: 1, assistantInterruption: state });
}

function readStoredAssistantInterruptionReaction(
  toolPayload: string | null | undefined,
): AssistantInterruptionReactionInput | null {
  const root = readToolPayloadRecord(toolPayload);
  return readAssistantInterruptionReaction(
    root?.assistantInterruptionReaction,
  ) ?? null;
}

function findPersistedAssistantInterruptionReaction(args: {
  db: DatabaseSync;
  userId: string;
  conversationId: string;
  sourceMessageId: string;
}): {
  id: string;
  receipt: AssistantInterruptionReactionInput;
} | null {
  const rows = args.db
    .prepare(
      `SELECT id, tool_payload
         FROM messages
        WHERE user_id = ?
          AND conversation_id = ?
          AND role = 'assistant'
          AND tool_payload IS NOT NULL
        ORDER BY created_at DESC, rowid DESC`,
    )
    .all(args.userId, args.conversationId) as Array<{
    id: string;
    tool_payload: string | null;
  }>;
  for (const row of rows) {
    const receipt = readStoredAssistantInterruptionReaction(row.tool_payload);
    if (receipt?.assistantMessageId === args.sourceMessageId) {
      return { id: row.id, receipt };
    }
  }
  return null;
}

function updateAssistantInterruptionClaim(args: {
  db: DatabaseSync;
  userId: string;
  messageId: string;
  expectedToolPayload: string;
  state: StoredAssistantInterruptionState;
}): boolean {
  const result = args.db
    .prepare(
      `UPDATE messages
          SET tool_payload = ?
        WHERE id = ? AND user_id = ? AND tool_payload = ?`,
    )
    .run(
      serializeStoredAssistantInterruptionState(args.state),
      args.messageId,
      args.userId,
      args.expectedToolPayload,
    );
  return result.changes === 1;
}

function readZenPersonaTransition(
  value: unknown,
): Required<ZenPersonaTransitionInput> | undefined {
  if (!value || typeof value !== "object") return undefined;
  const record = value as Record<string, unknown>;
  if (record.source !== "picker") return undefined;
  const fromBotId =
    typeof record.fromBotId === "string" && record.fromBotId.trim().length > 0
      ? record.fromBotId.trim()
      : null;
  const toBotId =
    typeof record.toBotId === "string" && record.toBotId.trim().length > 0
      ? record.toBotId.trim()
      : null;
  const style =
    record.style === "previous-introduces"
      ? "previous-introduces"
      : "new-speaks";
  return { fromBotId, toBotId, source: "picker", style };
}

function readZenAutonomy(value: unknown): ZenAutonomyInput | undefined {
  if (!value || typeof value !== "object") return undefined;
  const record = value as Record<string, unknown>;
  if (record.source !== "idle") return undefined;
  const activeBotId =
    typeof record.activeBotId === "string" &&
    record.activeBotId.trim().length > 0
      ? record.activeBotId.trim()
      : null;
  const idleMs =
    typeof record.idleMs === "number" && Number.isFinite(record.idleMs)
      ? Math.max(0, Math.round(record.idleMs))
      : 0;
  const clientTurnId =
    typeof record.clientTurnId === "string" &&
    record.clientTurnId.trim().length > 0
      ? record.clientTurnId.trim().slice(0, 80)
      : randomId(8);
  return { source: "idle", activeBotId, idleMs, clientTurnId };
}

function readAskQuestionPenaltyLevel(
  value: unknown,
): PrismMoodIgnoredQuestionPenaltyLevel | undefined {
  return value === "light" || value === "normal" || value === "elevated"
    ? value
    : undefined;
}

function readZenAskQuestionPatience(
  value: unknown,
): ZenAskQuestionPatienceInput | undefined {
  if (!value || typeof value !== "object") return undefined;
  const record = value as Record<string, unknown>;
  if (record.source !== "ask_question_patience") return undefined;
  const activeBotId =
    typeof record.activeBotId === "string" &&
    record.activeBotId.trim().length > 0
      ? record.activeBotId.trim()
      : null;
  const assistantMessageId =
    typeof record.assistantMessageId === "string" &&
    record.assistantMessageId.trim().length > 0
      ? record.assistantMessageId.trim().slice(0, 120)
      : undefined;
  const prompt =
    typeof record.prompt === "string" && record.prompt.trim().length > 0
      ? record.prompt.trim().replace(/\s+/g, " ").slice(0, 500)
      : undefined;
  const options = Array.isArray(record.options)
    ? record.options
        .map((option) => {
          if (!option || typeof option !== "object") return null;
          const row = option as Record<string, unknown>;
          const id =
            typeof row.id === "string" && row.id.trim().length > 0
              ? row.id.trim().slice(0, 80)
              : null;
          const label =
            typeof row.label === "string" && row.label.trim().length > 0
              ? row.label.trim().replace(/\s+/g, " ").slice(0, 160)
              : null;
          return id && label ? { id, label } : null;
        })
        .filter(
          (option): option is { id: string; label: string } => option !== null,
        )
        .slice(0, 4)
    : undefined;
  const timeoutMs =
    typeof record.timeoutMs === "number" && Number.isFinite(record.timeoutMs)
      ? Math.max(0, Math.round(record.timeoutMs))
      : undefined;
  const activeElapsedMs =
    typeof record.activeElapsedMs === "number" &&
    Number.isFinite(record.activeElapsedMs)
      ? Math.max(0, Math.round(record.activeElapsedMs))
      : undefined;
  const penaltyLevel = readAskQuestionPenaltyLevel(record.penaltyLevel);
  const clientTurnId =
    typeof record.clientTurnId === "string" &&
    record.clientTurnId.trim().length > 0
      ? record.clientTurnId.trim().slice(0, 80)
      : randomId(8);
  return {
    source: "ask_question_patience",
    activeBotId,
    ...(assistantMessageId ? { assistantMessageId } : {}),
    ...(prompt ? { prompt } : {}),
    ...(options && options.length > 0 ? { options } : {}),
    ...(timeoutMs !== undefined ? { timeoutMs } : {}),
    ...(activeElapsedMs !== undefined ? { activeElapsedMs } : {}),
    ...(penaltyLevel ? { penaltyLevel } : {}),
    clientTurnId,
  };
}

function readComposerRecentMessages(
  value: unknown,
): Array<{ role: "user" | "assistant"; content: string; botName?: string }> {
  if (!Array.isArray(value)) return [];
  return value
    .map((item) => {
      if (!item || typeof item !== "object") return null;
      const record = item as Record<string, unknown>;
      const role =
        record.role === "assistant"
          ? "assistant"
          : record.role === "user"
            ? "user"
            : null;
      if (!role || typeof record.content !== "string") return null;
      const content = record.content.trim().replace(/\s+/g, " ");
      if (!content) return null;
      const botName =
        typeof record.botName === "string" && record.botName.trim().length > 0
          ? record.botName.trim().slice(0, 80)
          : undefined;
      return {
        role,
        content:
          content.length > COMPOSER_RANDOM_PROMPT_MAX_MESSAGE_CHARS
            ? `${content.slice(0, COMPOSER_RANDOM_PROMPT_MAX_MESSAGE_CHARS).trim()}...`
            : content,
        ...(botName ? { botName } : {}),
      };
    })
    .filter(
      (
        item,
      ): item is {
        role: "user" | "assistant";
        content: string;
        botName?: string;
      } => item !== null,
    )
    .slice(-COMPOSER_RANDOM_PROMPT_MAX_CONTEXT_MESSAGES);
}

function clampComposerContextText(text: string, maxChars: number): string {
  const normalized = text.trim().replace(/\s+/g, " ");
  return normalized.length > maxChars
    ? `${normalized.slice(0, maxChars).trim()}...`
    : normalized;
}

function extractComposerRandomPromptValue(value: unknown): string | null {
  if (typeof value === "string") return value;
  if (!value || typeof value !== "object") return null;
  const record = value as Record<string, unknown>;
  for (const key of ["prompt", "message", "text", "suggestion", "value"]) {
    const candidate = record[key];
    if (typeof candidate === "string") return candidate;
  }
  return null;
}

function normalizeComposerRandomPromptResponse(raw: string): string {
  const cleaned = raw.trim();
  if (!cleaned) {
    throw new Error("Random prompt returned an empty result.");
  }
  const fenced = cleaned.match(/^```(?:json|JSON)?\s*\n([\s\S]*?)\n```$/);
  const unwrapped = fenced?.[1]?.trim() ?? cleaned;
  let candidate: string | null = null;
  try {
    const parsed = JSON.parse(unwrapped) as unknown;
    candidate = Array.isArray(parsed)
      ? extractComposerRandomPromptValue(parsed[0])
      : extractComposerRandomPromptValue(parsed);
  } catch {
    candidate = unwrapped;
  }
  const normalized = (candidate ?? "")
    .replace(/^["'“”]+|["'“”]+$/g, "")
    .replace(/^\s*(?:prompt|user|message|suggestion)\s*:\s*/i, "")
    .replace(/^\s*(?:[-*]|\d+[.)])\s+/, "")
    .replace(/\s+/g, " ")
    .trim();
  if (!normalized) {
    throw new Error("Random prompt returned an empty result.");
  }
  return normalized.length > COMPOSER_RANDOM_PROMPT_MAX_OUTPUT_CHARS
    ? normalized.slice(0, COMPOSER_RANDOM_PROMPT_MAX_OUTPUT_CHARS).trim()
    : normalized;
}

function readBotSemanticFacetSummary(raw: string | null | undefined): string[] {
  if (!raw || raw.trim().length === 0) return [];
  try {
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    const lines: string[] = [];
    for (const key of [
      "domains",
      "values",
      "tensions",
      "starterSeeds",
      "canonAnchors",
    ]) {
      const values = parsed[key];
      if (!Array.isArray(values)) continue;
      const compact = values
        .filter(
          (item): item is string =>
            typeof item === "string" && item.trim().length > 0,
        )
        .slice(0, 4)
        .map((item) => item.trim());
      if (compact.length > 0) {
        lines.push(`${key}: ${compact.join(", ")}`);
      }
    }
    return lines.slice(0, 6);
  } catch {
    return [];
  }
}

function clampConnectionScore(value: number): number {
  if (!Number.isFinite(value)) return 50;
  return Math.max(0, Math.min(100, Math.round(value)));
}

function connectionBandFromScore(score: number): OpinionBand {
  if (score >= 68) return "trusting";
  if (score <= 34) return "guarded";
  return "warming";
}

function readConnectionTrend(value: unknown): OpinionTrend {
  return value === "up" || value === "down" || value === "steady"
    ? value
    : "steady";
}

function readConnectionReasons(value: unknown, fallback: string): string[] {
  const reasons = Array.isArray(value)
    ? value.filter((item): item is string => typeof item === "string")
    : [];
  const cleaned = [fallback, ...reasons]
    .map((reason) => reason.trim())
    .filter((reason) => reason.length > 0);
  return Array.from(new Set(cleaned)).slice(0, 4);
}

function parseConversationBotGroupIds(
  raw: string | null | undefined,
): string[] {
  if (!raw || typeof raw !== "string") return [];
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(
      (value): value is string => typeof value === "string" && value.length > 0,
    );
  } catch {
    return [];
  }
}

function parseConversationCoffeeSeatBotIds(
  raw: string | null | undefined,
): Array<string | null> {
  if (!raw || typeof raw !== "string") return [];
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (!Array.isArray(parsed) || !parsed.some((value) => value === null))
      return [];
    const seats = parsed
      .slice(0, 5)
      .map((value) =>
        typeof value === "string" && value.length > 0 ? value : null,
      );
    while (seats.length < 5) seats.push(null);
    return seats;
  } catch {
    return [];
  }
}

function parseSourceMessageIds(raw: string | null | undefined): string[] {
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed)
      ? parsed.filter((value): value is string => typeof value === "string")
      : [];
  } catch {
    return [];
  }
}

function createSession(userId: string): { token: string; expiresAt: string } {
  const token = randomId(24);
  const expiresAt = new Date(
    Date.now() + config.sessionTtlHours * 60 * 60 * 1000,
  ).toISOString();
  db.prepare(
    "INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)",
  ).run(token, userId, expiresAt);
  return { token, expiresAt };
}

function touchUserActivity(userId: string): void {
  db.prepare("UPDATE users SET last_active_at = ? WHERE id = ?").run(
    new Date().toISOString(),
    userId,
  );
}

function replayRecordingIdsForSource(
  userId: string,
  surface: "signal" | "coffee",
  sourceIds: readonly string[],
): string[] {
  if (sourceIds.length === 0) return [];
  const find = db.prepare(
    "SELECT id FROM replay_recordings WHERE user_id = ? AND surface = ? AND source_id = ?",
  );
  return sourceIds.flatMap((sourceId) => {
    const row = find.get(userId, surface, sourceId) as
      { id: string } | undefined;
    return row ? [row.id] : [];
  });
}

function removeReplayDirectories(
  userId: string,
  recordingIds: readonly string[],
): void {
  for (const recordingId of recordingIds) {
    try {
      removeReplayRecordingDirectory(userId, recordingId);
    } catch {
      // Database deletion remains authoritative; list pruning removes stragglers.
    }
  }
}

async function deleteUserAccount(userId: string): Promise<void> {
  const resumeSlateRecovery = await retireAndPurgeSlateRecoveryProjects(
    userId,
    slateProjectIdsForUser(userId),
  );
  db.exec("BEGIN IMMEDIATE TRANSACTION");
  try {
    db.prepare("DELETE FROM sessions WHERE user_id = ?").run(userId);
    db.prepare("DELETE FROM client_access_tokens WHERE user_id = ?").run(
      userId,
    );
    db.prepare("DELETE FROM conversation_exports WHERE user_id = ?").run(
      userId,
    );
    db.prepare("DELETE FROM images WHERE user_id = ?").run(userId);
    db.prepare("DELETE FROM bots WHERE user_id = ?").run(userId);
    db.prepare("DELETE FROM memory_summaries WHERE user_id = ?").run(userId);
    db.prepare("DELETE FROM memories WHERE user_id = ?").run(userId);
    db.prepare("DELETE FROM messages WHERE user_id = ?").run(userId);
    db.prepare("DELETE FROM conversations WHERE user_id = ?").run(userId);
    db.prepare("DELETE FROM users WHERE id = ?").run(userId);
    db.exec("COMMIT");
  } catch (error) {
    db.exec("ROLLBACK");
    resumeSlateRecovery();
    throw error;
  }

  try {
    removeGeneratedImagesDirectoryForUser(userId);
  } catch {
    // Best-effort filesystem cleanup after SQLite removes image rows.
  }
  try {
    removeAssetCleanupTrashDirectoryForUser(userId);
  } catch {
    // Best-effort recovery-trash cleanup after SQLite removes the account.
  }
  try {
    removeReplayMediaForUser(userId);
  } catch {
    // Best-effort replay cleanup after SQLite removes the account.
  }

  try {
    await deleteVectorsForUser(userId);
  } catch {
    // Qdrant cleanup is best-effort; account data is already removed from SQLite.
  }
}

async function restoreUserFactoryDefaults(userId: string): Promise<void> {
  const resumeSlateRecovery = await retireAndPurgeSlateRecoveryProjects(
    userId,
    slateProjectIdsForUser(userId),
  );
  try {
    restoreFactoryDefaultsInDatabase(db, userId);
  } catch (error) {
    resumeSlateRecovery();
    throw error;
  }

  try {
    removeGeneratedImagesDirectoryForUser(userId);
  } catch {
    // Best-effort filesystem cleanup after SQLite removes image rows.
  }
  try {
    removeAssetCleanupTrashDirectoryForUser(userId);
  } catch {
    // Best-effort recovery-trash cleanup after SQLite resets the account.
  }
  try {
    removeReplayMediaForUser(userId);
  } catch {
    // Best-effort replay cleanup after SQLite resets the account.
  }

  try {
    await deleteVectorsForUser(userId);
  } catch {
    // Qdrant cleanup is best-effort; account data is already reset in SQLite.
  }
}

async function purgeInactiveAccounts(): Promise<void> {
  const cutoffIso = getInactiveAccountCutoff().toISOString();
  const inactiveUsers = db
    .prepare(
      "SELECT id FROM users WHERE COALESCE(last_active_at, created_at) < ?",
    )
    .all(cutoffIso) as Array<{ id: string }>;

  for (const user of inactiveUsers) {
    await deleteUserAccount(user.id);
  }
}

function mapImageRowToClient(row: {
  id: string;
  prompt: string;
  revised_prompt: string | null;
  url: string;
  size: string;
  quality: string;
  provider: string;
  bot_id: string | null;
  related_bot_ids: string | null;
  origin: string | null;
  created_at: string;
  local_rel_path: string | null;
  model: string | null;
  purpose?: string | null;
}): Record<string, unknown> {
  const hasLocalFile = Boolean(row.local_rel_path?.trim());
  const displayUrl = hasLocalFile
    ? `/api/images/${encodeURIComponent(row.id)}/file`
    : row.url;
  return {
    id: row.id,
    botId: row.bot_id,
    botIds: normalizeImageRelatedBotIds(row.related_bot_ids, row.bot_id),
    origin: row.origin ?? "images_panel",
    prompt: row.prompt,
    revisedPrompt: row.revised_prompt,
    size: row.size,
    quality: row.quality,
    provider: row.provider,
    model: row.model ?? DEFAULT_OPENAI_IMAGE_MODEL_ID,
    purpose: row.purpose ?? "gallery",
    createdAt: row.created_at,
    url: row.url,
    localRelPath: row.local_rel_path,
    displayUrl,
    hasLocalFile,
  };
}

